from taf.ul.trs_e2e_fw.lib.utils.decorators import check_rat
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_cu.base import BaseClass
from taf.ul.trs_e2e_fw.lib.utils.verification.alarms import AlarmsVerification
from taf.ul.trs_e2e_fw.lib.ems.exceptions import AlarmParameterNotFoundException
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()

class Alarms(BaseClass):
    """Alarms"""
    def __init__(self):
        super(Alarms, self).__init__()
        self.alarm_details = list()

    @check_rat
    def verify_alarm(self, **kwargs):
        """This function searches for alarm
        :param faultid: fault id of the alarm
        :param rat: supported values l|w|g. The RAT which the alarm belongs to.
        :param alarm_type: active | history
        :param severity: Alarm severity (critical, major, minor or warning)
        :param should_exist(bool): Should the alarm exist or not, ${False} or ${True}
        :param occurrences: The number of instances expected for the alarm
        :param check_unexpected_alarms: Boolean to validate unexpected alarms
                                        or not
        :param expected_alarms: A list of faultids which will be ignored during
                                validation
        :param prev_alarms: Alarms Json for validating against the current
                            alarms
        :param timeout: Time to wait for positive procedure result
        :param alias: Name of execution context
        :raises: exception based on should_exist argument
        """

        faultid = kwargs.get("faultid", None)
        alarm_type = kwargs.get("alarm_type", 'active')
        severity = kwargs.get("severity", None)
        should_exist = kwargs.get("should_exist", True)
        occurrences = kwargs.get("occurrences", 1)
        check_unexpected_alarms = kwargs.get("check_unexpected_alarms", False)
        expected_alarms = kwargs.get("expected_alarms", [])
        prev_alarms = kwargs.get("prev_alarms", None)
        if len(expected_alarms) > 0:
            expected_alarms = [int(x) for x in expected_alarms]
        timeout = kwargs.get("timeout", 300)
        alias = kwargs.get("alias", 'default')
        if faultid:
            faultid = int(faultid)
        # should_exist = bool(should_exist)
        if isinstance(should_exist, str):
            should_exist = should_exist.lower() in ('true', '1', 'yes', 'on')
        else:
            should_exist = bool(should_exist)
        occurrences = int(occurrences)
        interface = 'cu'
        if severity:
            severity=[severity]

        return getattr(self, "_verify_in_{}_alarms".format(
            alarm_type.lower()))(faultid, severity, should_exist, occurrences,
                                 check_unexpected_alarms, expected_alarms,
                                 prev_alarms, timeout, interface, alias)

    def _verify_in_active_alarms(self, faultid, severity, should_exist,
                                 occurrences, check_unexpected_alarms,
                                 expected_alarms, prev_alarms,
                                 timeout,interface, alias):
        logger.debug("Getting active alarms....")
        alarm_object_list = self.factory.cu_oam.get_active_alarms(
            filter_by_severity=severity, items_per_page=20, timeout=float(timeout), connection=alias, use_m2m=False)
        alarm_object_list = alarm_object_list['alarms']
        logger.info("alarms list {}".format(alarm_object_list))
        alarm_object_list = self.convert_alarm_format(alarm_object_list, interface)
        AlarmsVerification().write_alarms_to_file('active_alarms.json', alarm_object_list)
        AlarmsVerification().verify_alarm_exists_and_validate_with_rise(alarm_object_list,
                                                                        check_unexpected_alarms,
                                                                        prev_alarms,
                                                                        expected_alarms,
                                                                        faultid,
                                                                        occurrences,
                                                                        should_exist,
                                                                        alias, interface)
        logger.info('alarms to be returned')
        logger.info(alarm_object_list)
        return alarm_object_list

    def _verify_in_history_alarms(self, faultid, severity, should_exist,
                                  occurrences, check_unexpected_alarms,
                                  expected_alarms, prev_alarms,
                                  timeout, interface, alias):
        logger.debug("Getting historical alarms....")
        alarm_object_list = self.factory.cu_oam.get_historical_alarms(
            filter_by_severity=severity, items_per_page=20, timeout=float(timeout), connection=alias, use_m2m=False)
        alarm_object_list = alarm_object_list['alarms']
        logger.info("alarms list {}".format(alarm_object_list))
        alarm_object_list = self.convert_alarm_format(alarm_object_list, interface)
        AlarmsVerification().write_alarms_to_file('history_alarms.json', alarm_object_list)
        AlarmsVerification().verify_alarm_exists_and_validate_with_rise(alarm_object_list,
                                                                        check_unexpected_alarms,
                                                                        prev_alarms,
                                                                        expected_alarms,
                                                                        faultid,
                                                                        occurrences,
                                                                        should_exist,
                                                                        alias, interface)
        logger.info('alarms to be returned')
        logger.info(alarm_object_list)
        return alarm_object_list

    def convert_alarm_format(self, alarms_object_format, interface):
        """Convert alarm format"""
        alarms_general_format = list()
        for alarm_details in alarms_object_format:
            alarm_dictionary = dict()
            alarm_dictionary['#'] = alarms_object_format.index(alarm_details) + 1
            try:
                alarm_dictionary['OBJECT'] = alarm_details['alarming_object']
                alarm_dictionary['SEVERITY'] = alarm_details['severity']
                alarm_dictionary['TEXT'] = alarm_details['alarm_name']
                alarm_dictionary['ALARM ID'] = alarm_details['alarm_id']
                alarm_dictionary['FAULT NAME'] = alarm_details['fault_name']
                alarm_dictionary['TIME'] = AlarmsVerification().convert_date_format(alarm_details['appear_time'], interface)
                alarm_dictionary['FAULT ID'] = alarm_details['fault_id']
                alarm_dictionary['ADDITIONAL INFO'] = alarm_details['additional_info']
            except KeyError as keyError:
                raise AlarmParameterNotFoundException("alarm parameter {} not found".format(
                    keyError))
            except AlarmParameterNotFoundException as e:
                raise AlarmParameterNotFoundException("alarm parameter {} not found".format(
                    e))
            alarm_dictionary_final = {
                key.decode() if isinstance(key, bytes) else key:
                val.decode() if isinstance(val, bytes) else val
                for key, val in alarm_dictionary.items()}

            alarms_general_format.append(alarm_dictionary_final)
        logger.debug("Converted format:{}".format(alarms_general_format))
        return alarms_general_format

    @check_rat
    def get_active_alarms_summary(self, **kwargs):
        """
        Gets the dict of active alarms summary and total number of them.

        .. note::
            SUPPORTS INTERNAL AND M2M API

        :param Union[int,str, float] timeout: (optional) Timeout for the operation.
        :param str connection: (optional) Unique identifier for a certain connections.
        :param bool use_m2m: (optional applicable only for release cuoam_21b or newer) m2m feature activation flag.
                             If set to False, internal API will be used instead of licensed API (M2M).
                             Defaults set to True.
        :param str alarm_type: active or historical alarms.
        :return: dict with keys:
            - 'total': optional, the value is total amount of alarms as int
            - 'severity': the value is dict with severities and their number of occurrences
        """
        alarm_type = kwargs.get("alarm_type", "active")
        use_m2m = kwargs.get("use_m2m", True)
        timeout = kwargs.get("timeout", 300)
        alias = kwargs.get("alias", 'default')
        if alarm_type == "active:":
            return self.factory.cu_oam.get_active_alarms_summary(use_m2m=use_m2m, timeout=float(timeout), connection=alias)
        else:
            return self.factory.cu_oam.get_historical_alarms_summary(timeout=float(timeout), connection=alias)
